// ---------- player input and moment-to-moment play ----------
const touchActive=matchMedia('(pointer:coarse)').matches;let stickVec={x:0,y:0},fireHeld=false,lookLast=null;
function moveBlocked(x,z){if(Math.hypot(x,z)>21.15)return true;for(const b of blockRects){const nx=clamp(x,b.x-b.w/2-.48,b.x+b.w/2+.48),nz=clamp(z,b.z-b.d/2-.48,b.z+b.d/2+.48);if((x-nx)**2+(z-nz)**2<.24)return true}return false}
