document.getElementById('randomTouch').addEventListener('pointerdown',()=>randomize(true));

// ---------- simulation loop ----------
const clock=new THREE.Clock();let walkCycle=0;
function update(dt){if(!active)return;gameTime+=dt;elapsed+=dt;shotCooldown=Math.max(0,shotCooldown-dt);dashCooldown=Math.max(0,dashCooldown-dt);invuln=Math.max(0,invuln-dt);rerollTimer-=dt;if(rerollTimer<=0){randomize(false);showMessage('AUTO REROLL','NEW WEAPON // EVERY 12 SECONDS')};if(fireHeld&&shotCooldown<=0)doShoot();
const forward=new THREE.Vector3(Math.sin(player.yaw),0,Math.cos(player.yaw));const right=new THREE.Vector3(Math.cos(player.yaw),0,-Math.sin(player.yaw));let mx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+stickVec.x;let mz=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)-stickVec.y;const mag=Math.hypot(mx,mz);if(mag>1){mx/=mag;mz/=mag}const move=right.multiplyScalar(mx).add(forward.multiplyScalar(mz));if(move.lengthSq()>.01){move.normalize();const speed=keys.ShiftLeft?8.6:6.1;const nx=player.pos.x+move.x*speed*dt,nz=player.pos.z+move.z*speed*dt;if(!moveBlocked(nx,player.pos.z))player.pos.x=nx;if(!moveBlocked(player.pos.x,nz))player.pos.z=nz;player.yaw=Math.atan2(move.x,move.z);walkCycle+=dt*11}else walkCycle+=dt*2;
if(player.onGround===false){player.vel.y-=18*dt;player.pos.y+=player.vel.y*dt;if(player.pos.y<=0){player.pos.y=0;player.vel.y=0;player.onGround=true}}
playerModel.position.copy(player.pos);playerModel.position.y+=Math.sin(walkCycle)*.025;playerModel.rotation.y=player.yaw;
const camTarget=player.pos.clone().add(new THREE.Vector3(0,1.35,0));const camForward=new THREE.Vector3(Math.sin(player.yaw),0,Math.cos(player.yaw));const desired=camera.position.clone();desired.copy(player.pos).addScaledVector(camForward,-7.2);desired.x+=Math.cos(player.yaw)*1.15;desired.y=player.pos.y+3.45;desired.z-=Math.sin(player.yaw)*1.15;camera.position.lerp(desired,1-Math.exp(-7*dt));const lookTarget=camTarget.clone().addScaledVector(camForward,11);lookTarget.y+=Math.tan(player.pitch)*10;camera.lookAt(lookTarget);
for(const bot of bots){if(!bot.alive)continue;const delta=player.pos.clone().sub(bot.pos);delta.y=0;const dist=delta.length();bot.model.rotation.y=Math.atan2(delta.x,delta.z);if(bot.stun>0)bot.stun-=dt;else if(dist>4.1){delta.normalize();const speed=bot.speed*(dist<7?.48:1);const nx=bot.pos.x+delta.x*speed*dt,nz=bot.pos.z+delta.z*speed*dt;if(!moveBlocked(nx,bot.pos.z))bot.pos.x=nx;if(!moveBlocked(bot.pos.x,nz))bot.pos.z=nz}if(dist<17){bot.fire-=dt;if(bot.fire<=0){botFire(bot);bot.fire=rand(1.05,2.1)-Math.min(roundNum*.05,.4)}}bot.model.position.set(bot.pos.x,Math.sin(elapsed*4+bots.indexOf(bot))*.035,bot.pos.z)}
for(let i=effects.length-1;i>=0;i--){const e=effects[i];e.life-=dt;e.mesh.material.opacity=Math.max(0,e.life/e.max);if(e.scale>1){const s=1+(1-e.life/e.max)*e.scale;e.mesh.scale.setScalar(s)}if(e.life<=0){scene.remove(e.mesh);e.mesh.geometry.dispose();e.mesh.material.dispose();effects.splice(i,1)}}
if(announceTimer>0){announceTimer-=dt;if(announceTimer<=0)ui.announce.classList.remove('show')}if(hitTimer>0){hitTimer-=dt;if(hitTimer<=0)ui.hitmark.classList.remove('show')}if(kills>=10){finishGame()}updateHUD();
}
function render(){requestAnimationFrame(render);const dt=Math.min(clock.getDelta(),.04);update(dt);const t=clock.elapsedTime;arena.rotation.y=Math.sin(t*.035)*.012;pinkLight.intensity=25+Math.sin(t*1.7)*5;blueLight.intensity=22+Math.cos(t*1.2)*4;renderer.render(scene,camera)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))});
spawnPlayer();fillBots();randomize(false);render();
</script>
</body>
</html>

