function doShoot(){
 if(!active||dead||shotCooldown>0)return;
 shotCooldown=currentWeapon.rate;
 const origin=camera.position.clone(),targetMeshes=bots.filter(b=>b.alive).map(b=>b.model);
 let hitAny=false;
 for(let pellet=0;pellet<currentWeapon.shots;pellet++){
  const direction=new THREE.Vector3();camera.getWorldDirection(direction);
  direction.x+=rand(-currentWeapon.spread,currentWeapon.spread);direction.y+=rand(-currentWeapon.spread,currentWeapon.spread);direction.z+=rand(-currentWeapon.spread,currentWeapon.spread);direction.normalize();
  raycaster.set(origin,direction);raycaster.far=currentWeapon.range;
  const hits=raycaster.intersectObjects(targetMeshes,true);let end=origin.clone().addScaledVector(direction,currentWeapon.range);
  if(hits.length){
   const hit=hits[0];end.copy(hit.point);let node=hit.object,found=null;
   while(node&&!found){found=bots.find(b=>b.alive&&b.model===node);node=node.parent}
   if(found){hitAny=true;damageBot(found,currentWeapon.damage);if(currentWeapon.blast){for(const b of bots)if(b!==found&&b.alive&&b.pos.distanceTo(found.pos)<currentWeapon.blast)damageBot(b,currentWeapon.damage*.55)}}
  }
  makeBeam(origin.clone().addScaledVector(direction,.7),end,currentWeapon.color,currentWeapon.name==='Rail Driver'?.08:.04,currentWeapon.name==='Rail Driver'?.2:.11);
 }
 if(hitAny){ui.hitmark.classList.add('show');hitTimer=.16}
 makeBurst(origin.clone().add(camera.getWorldDirection(new THREE.Vector3()).multiplyScalar(1)),currentWeapon.color,.18);
 if(currentWeapon.name==='Void Slicer'){
  const nearest=bots.filter(b=>b.alive&&b.pos.distanceTo(player.pos)<currentWeapon.range).sort((a,b)=>a.pos.distanceTo(player.pos)-b.pos.distanceTo(player.pos))[0];
  if(nearest){damageBot(nearest,currentWeapon.damage);makeBeam(player.pos.clone().add(new THREE.Vector3(0,1,0)),nearest.pos.clone().add(new THREE.Vector3(0,1,0)),currentWeapon.color,.13,.17)}
 }
}

