import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
if(process.platform==='linux') process.env.DISPLAY ||= ':'+readFileSync(join(runtime,'display'),'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1024,height:768}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.route('http://localhost:3002/**',async route=>{
 const resp=await route.fetch(); const u=new URL(route.request().url());
 if(u.pathname==='/') {let body=await resp.text();body=body.replace('spawnPlayer();fillBots();randomize(false);render();','window.__gameTest=()=>({bots:bots.filter(b=>b.alive).map(b=>({pos:b.pos.toArray(),hp:b.hp})),camera,player,weapon:currentWeapon.name,gameTime});spawnPlayer();fillBots();randomize(false);render();'); await route.fulfill({response:resp,body});} else await route.continue();
});
await page.goto('http://localhost:3002/');
await page.locator('#playBtn').click();
await page.waitForTimeout(600);
console.log('pointer locked',await page.evaluate(()=>document.pointerLockElement===renderer.domElement));
let cursor={x:512,y:384};
await page.mouse.move(cursor.x,cursor.y);
for(let tries=0;tries<24;tries++){
 const s=await page.evaluate(()=>{let {bots,camera}=window.__gameTest();let list=bots.map(b=>{const p=new THREE.Vector3(b.pos[0],b.pos[1]+1.15,b.pos[2]);p.project(camera);return {x:(p.x+1)*innerWidth/2,y:(1-p.y)*innerHeight/2,z:p.z,hp:b.hp}}).filter(p=>p.z>0&&p.x>10&&p.x<1014&&p.y>10&&p.y<758);return list.sort((a,b)=>(a.x-512)**2+(a.y-384)**2-((b.x-512)**2+(b.y-384)**2))[0]});
 if(!s)break;
 const dx=Math.max(-120,Math.min(120,(s.x-512)*.72));
 const dy=Math.max(-100,Math.min(100,(s.y-384)*.88));
 cursor={x:Math.max(1,Math.min(1023,cursor.x+dx)),y:Math.max(1,Math.min(767,cursor.y+dy))};
 await page.mouse.move(cursor.x,cursor.y);await page.waitForTimeout(160);
 await page.mouse.down();await page.waitForTimeout(35);await page.mouse.up();await page.waitForTimeout(250);
 const state=await page.evaluate(()=>({elims:document.querySelector('#elims').textContent,hp:document.querySelector('#hpnum').textContent,feed:document.querySelector('#feed').innerText}));
 console.log('aim/fire',tries,JSON.stringify({proj:s,state}));
 if(state.elims!=='00')break;
}
await page.waitForTimeout(500);
console.log('final',await page.evaluate(()=>({elims:document.querySelector('#elims').textContent,hp:document.querySelector('#hpnum').textContent,weapon:document.querySelector('#weaponName').textContent,timer:document.querySelector('#timer').textContent,feed:document.querySelector('#feed').innerText})));
await page.screenshot({path:'/tmp/opencode/chaos-playing-final.jpg',type:'jpeg',quality:90});
console.log('errors',errors);
await browser.close();

