import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
if(process.platform==='linux') process.env.DISPLAY ||= ':'+readFileSync(join(runtime,'display'),'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1024,height:768}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.route('http://localhost:3002/**',async route=>{
 const resp=await route.fetch(); const u=new URL(route.request().url());
 if(u.pathname==='/') {let body=await resp.text();body=body.replace('spawnPlayer();fillBots();randomize(false);render();','window.__gameTest=()=>({pos:player.pos.toArray(),weapon:currentWeapon.name,rerollTimer,gameTime});spawnPlayer();fillBots();randomize(false);render();'); await route.fulfill({response:resp,body});} else await route.continue();
});
await page.goto('http://localhost:3002/');
await page.locator('#playBtn').click();
await page.waitForTimeout(300);
const beforeMove=await page.evaluate(()=>window.__gameTest().pos);
await page.keyboard.down('KeyW');await page.waitForTimeout(400);await page.keyboard.up('KeyW');
const afterMove=await page.evaluate(()=>window.__gameTest().pos);
const weaponBefore=await page.evaluate(()=>window.__gameTest().weapon);
await page.keyboard.press('KeyR');await page.waitForTimeout(100);
const manual=await page.evaluate(()=>({weapon:window.__gameTest().weapon,timer:window.__gameTest().rerollTimer,feed:document.querySelector('#feed').innerText}));
await page.waitForTimeout(12300);
const timed=await page.evaluate(()=>({weapon:window.__gameTest().weapon,timer:window.__gameTest().rerollTimer,gameTime:window.__gameTest().gameTime,message:document.querySelector('#announceMain').textContent,feed:document.querySelector('#feed').innerText,hp:document.querySelector('#hpnum').textContent,elims:document.querySelector('#elims').textContent}));
console.log(JSON.stringify({beforeMove,afterMove,weaponBefore,manual,timed,errors},null,2));
await page.screenshot({path:'/tmp/opencode/chaos-systems-final.jpg',type:'jpeg',quality:90});
await browser.close();

