import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
if(process.platform==='linux') process.env.DISPLAY ||= ':'+readFileSync(join(runtime,'display'),'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1024,height:768}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.route('http://localhost:3002/**',async route=>{
 const resp=await route.fetch(); const u=new URL(route.request().url());
 if(u.pathname==='/') {let body=await resp.text();body=body.replace('spawnPlayer();fillBots();randomize(false);render();','window.__gameTest=()=>({pos:player.pos.toArray(),weapon:currentWeapon.name,rerollTimer,gameTime,active,keys:{...keys}});window.__step=dt=>update(dt);spawnPlayer();fillBots();randomize(false);render();'); await route.fulfill({response:resp,body});} else await route.continue();
});
await page.goto('http://localhost:3002/');
await page.locator('#playBtn').click();
const initial=await page.evaluate(()=>window.__gameTest());
const movement=await page.evaluate(()=>{const before=window.__gameTest().pos;window.dispatchEvent(new KeyboardEvent('keydown',{code:'KeyW',bubbles:true}));window.__step(.4);window.dispatchEvent(new KeyboardEvent('keyup',{code:'KeyW',bubbles:true}));return {before,after:window.__gameTest().pos,keys:window.__gameTest().keys}});
const beforeAuto=await page.evaluate(()=>window.__gameTest());
await page.evaluate(()=>{for(let i=0;i<121;i++)window.__step(.1)});
const auto=await page.evaluate(()=>({state:window.__gameTest(),message:document.querySelector('#announceMain').textContent,feed:document.querySelector('#feed').innerText}));
console.log(JSON.stringify({initial,movement,beforeAuto,auto,errors},null,2));
await page.screenshot({path:'/tmp/opencode/chaos-systems-verified.jpg',type:'jpeg',quality:90});
await browser.close();

