import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
if(process.platform==='linux') process.env.DISPLAY ||= ':'+readFileSync(join(runtime,'display'),'utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1280,height:800}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.route('http://localhost:3002/**',async route=>{
 const resp=await route.fetch();const u=new URL(route.request().url());
 if(u.pathname==='/'){
  let body=await resp.text();
  body=body.replace('if(!touchActive)renderer.domElement.requestPointerLock?.()','if(!touchActive){}');
  const init='spawnPlayer();fillBots();randomize(false);render();';
  const expose=`window.__combat={weapons:()=>weapons.map(w=>w.name),state:()=>({weapon:currentWeapon.name,projectiles:projectiles.map(p=>({kind:p.kind,pos:p.pos.toArray()})),bots:bots.map(b=>({hp:b.hp,alive:b.alive,pos:b.pos.toArray()})),gunVisible:viewWeapon.visible,gunParent:viewWeapon.parent===camera}),setWeapon:n=>{currentWeapon=weapons.find(w=>w.name===n);if(viewWeapon)camera.remove(viewWeapon);viewWeapon=makeViewWeapon();shotCooldown=0},place:(x,z,yaw)=>{player.pos.set(x,0,z);player.yaw=yaw;player.pitch=-.03;updatePlayerCamera()},targets:coords=>{bots.forEach((b,i)=>{b.alive=i<coords.length;scene.remove(b.model);if(i<coords.length){b.pos.set(coords[i][0],0,coords[i][1]);b.model.position.set(coords[i][0],0,coords[i][1]);b.hp=b.maxHp=200;scene.add(b.model)}})},fire:()=>doShoot(),roll:()=>randomize(true)};spawnPlayer();fillBots();randomize(false);render();`;
  if(!body.includes(init))throw new Error('init sequence not found');
  body=body.replace(init,expose);await route.fulfill({response:resp,body});
 }else await route.continue();
});
await page.goto('http://localhost:3002/');
await page.locator('#playBtn').click();
const delay=ms=>new Promise(r=>setTimeout(r,ms));
const test={};
// Direct traveling projectile and bot collision.
await page.evaluate(()=>{__combat.setWeapon('Pulse Blaster');__combat.place(12,-12,0);__combat.targets([[12,-4]]);__combat.fire()});
test.projectileVisible=await page.evaluate(()=>__combat.state().projectiles.length>0);
await delay(220);
test.projectileHit=await page.evaluate(()=>({hp:__combat.state().bots[0].hp,remaining:__combat.state().projectiles.length}));
// A projectile aimed into the central arena cover should be consumed on impact.
await page.evaluate(()=>{__combat.setWeapon('Kinetic Pistol');__combat.place(0,4,0);__combat.targets([]);__combat.fire()});
await delay(260);
test.arenaImpact=await page.evaluate(()=>__combat.state().projectiles.length===0);
// Rocket hits one bot and splashes a nearby second bot.
await page.evaluate(()=>{__combat.setWeapon('Rocket Pop');__combat.place(12,-12,0);__combat.targets([[12,-4],[15,-4]]);__combat.fire()});
await delay(950);
test.rocketSplash=await page.evaluate(()=>__combat.state().bots.slice(0,2).map(b=>b.hp));
// Knife and dual-dagger strikes hit targets in reach and render as camera children.
for(const name of ['Combat Knife','Twin Daggers']){
 await page.evaluate(n=>{__combat.setWeapon(n);__combat.place(0,16,Math.PI);__combat.targets([[0,13.4]]);__combat.fire()},name);
 test[name]=await page.evaluate(()=>({hp:__combat.state().bots[0].hp,weapon:__combat.state().weapon,gunVisible:__combat.state().gunVisible,gunParent:__combat.state().gunParent}));
}
// Confirm randomized rolls can select every added weapon and all view models stay attached.
const rolls=await page.evaluate(()=>{const names=new Set();for(let i=0;i<500;i++){__combat.roll();names.add(__combat.state().weapon)}return {names:[...names],state:__combat.state()}});
test.randomized=rolls;
test.errors=errors;
console.log(JSON.stringify(test,null,2));
await browser.close();

